"""Generates STATUS.md. Never hand-edit the output."""
from . import core


def render():
    posts = core.all_posts()
    lines = ["# Birds Eye status", "",
             "_Generated by `python -m birdseye status`. Do not hand-edit._", "",
             "| Post | Format | Stage | Owner | Claim | Schedule (WIB) |",
             "|---|---|---|---|---|---|"]
    order = core.STAGES + core.SIDE
    for p in sorted(posts, key=lambda p: (order.index(p["status"]), p["id"])):
        c = p.get("claim")
        claim = f"{c['by']} until {c['until'][11:16]}" if c else ""
        tag = " _(example)_" if p.get("example") else ""
        lines.append(f"| {p['id']}{tag} | {p['format']} | {p['status']} | {p['owner']} | {claim} | "
                     f"{(p['schedule_at'] or '')[:16].replace('T', ' ')} |")
    wait = core.waiting_on_human(posts)
    lines += ["", f"## Waiting on you ({len(wait)})", ""]
    lines += [f"- **{w['what']}**: `{w['id']}`" for w in wait] or ["- nothing"]
    return "\n".join(lines) + "\n"


def write():
    f = core.root() / "STATUS.md"
    f.write_text(render())
    return f
